def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    total_in_thousands = v1 + v2
    value = total_in_thousands / 1000
    return {
        "value": value,
        "trace": {
            "total_in_thousands": total_in_thousands,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
